import csv
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from pathlib import Path


def to_money(value):
    try:
        return Decimal(value.strip())
    except (InvalidOperation, AttributeError):
        return Decimal("0")


def fmt(value):
    return str(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main():
    path = Path("дані") / "рахунки.csv"
    debts = defaultdict(Decimal)

    with path.open(encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            client = (row.get("клієнт") or "").strip()
            total = to_money(row.get("сума"))
            paid = to_money(row.get("сплачено"))
            debts[client] += total - paid

    debtors = [(client, debt) for client, debt in debts.items() if debt > 0]
    debtors.sort(key=lambda item: (-item[1], item[0]))

    total_debt = Decimal("0")
    for client, debt in debtors:
        print(f"{client}: {fmt(debt)}")
        total_debt += debt

    print(f"Разом: {fmt(total_debt)}")


if __name__ == "__main__":
    main()

